def find_cousins(n, parents, queries):
    # Create a dictionary to store the ancestors of each person
    ancestors = {i: [] for i in range(1, n + 1)}

    # Build the ancestor tree
    for i in range(1, n + 1):
        if parents[i - 1] != 0:
            ancestors[parents[i - 1]].append(i)

    # Function to find all ancestors of a person up to a certain depth
    def find_ancestors(person, depth):
        if depth == 0:
            return {person}
        result = {person}
        for ancestor in ancestors[person]:
            result.update(find_ancestors(ancestor, depth - 1))
        return result

    # Process each query
    results = []
    for vi, pi in queries:
        if pi == 0:
            results.append(0)
        else:
            vi_ancestors = find_ancestors(vi, pi)
            count = 0
            for other in range(1, n + 1):
                if other != vi and find_ancestors(other, pi) == vi_ancestors:
                    count += 1
            results.append(count)

    return results

